package net.oceancanvas.mod.worldgen;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.concurrent.atomic.AtomicLong;import java.util.concurrent.atomic.AtomicInteger;
class OceanCanvasNativeLightUpdateCostTest {
 @Test void originalExactlyOnceAndSampledAllocationMeasured(){var clock=new AtomicLong(10);var bytes=new AtomicLong(100);var n=new AtomicInteger();var o=new OceanCanvasNativeLightUpdateCost(clock::get,bytes::get);o.observe(128,()->{n.incrementAndGet();clock.addAndGet(40);bytes.addAndGet(300);});assertEquals(1,n.get());assertTrue(o.snapshot().contains("batch128to999=1"));assertTrue(o.snapshot().contains("sampledBytes=300"));assertTrue(o.snapshot().contains("totalNs=40"));}
 @Test void originalExceptionIdentityAndFinallyMetrics(){var c=new AtomicLong(10);var o=new OceanCanvasNativeLightUpdateCost(c::get,()->-1);var failure=new IllegalStateException("original");assertSame(failure,assertThrows(IllegalStateException.class,()->o.observe(1001,()->{c.addAndGet(5);throw failure;})));assertTrue(o.snapshot().contains("batch1000=1"));assertTrue(o.snapshot().contains("allocationUnavailable=1"));}
 @Test void onlyEvery64CallsReadsAllocation(){var reads=new AtomicInteger();var o=new OceanCanvasNativeLightUpdateCost(()->1,()->{reads.incrementAndGet();return 4;});for(int i=0;i<65;i++)o.observe(1,()->{});assertEquals(4,reads.get());assertTrue(o.snapshot().contains("calls=65"));assertTrue(o.snapshot().contains("allocationSamples=2"));}
 @Test void metricFailureAndBackwardClockCannotChangeOriginal(){var n=new AtomicInteger();var o=new OceanCanvasNativeLightUpdateCost(()->{throw new IllegalArgumentException();},()->-1);o.observe(0,n::incrementAndGet);assertEquals(1,n.get());assertTrue(o.snapshot().contains("zero=1"));assertTrue(o.snapshot().contains("totalNs=0"));}
}
